-- Approved Ducati factory documents and used ownership guidance.
-- Official source selectors: do not claim inspection of a particular PDF.
-- Uses same source-audited exact-model facts system and existing model design.
with documented(catalog_model_id,category,label,value,start_year,end_year,market,source_name,source_url,verification_basis,scope_note,source_version) as (values
(102,'factory_documents','Ducati Monster 937 — official owner manual archive','{"document_url":"https://www.ducati.com/gb/en/service-maintenance/owner-manuals","applicability":"Select the exact Monster 937 model year; manufacturer manuals differ across years","document_type":"Official owner manual finder","document_title":"Ducati owner manuals — select Monster and exact year","reference_year":"2021-generation onward"}'::jsonb,2021,NULL,'United Kingdom','Ducati official owner-manual archive','https://www.ducati.com/gb/en/service-maintenance/owner-manuals','official_factory_document_archive_verified_2026_11_12','This is the official selector, NOT a claim that a specific owner manual PDF has been downloaded or inspected.','Ducati official owner-manual archive'),
(104,'factory_documents','Ducati Multistrada V4 — official factory manuals and brochures','{"document_url":"https://www.ducati.com/ww/en/service-maintenance/manuals-genuine-parts-and-maintenance-schedules","applicability":"Choose the exact Multistrada V4 model and model year before using a manual or service schedule","document_type":"Manufacturer owner manual and brochure catalogue","document_title":"Ducati official factory documents — choose Multistrada V4 year"}'::jsonb,2021,NULL,'International factory archive','Ducati factory manuals, maintenance schedules and brochures library','https://www.ducati.com/ww/en/service-maintenance/manuals-genuine-parts-and-maintenance-schedules','official_factory_document_archive_verified_2026_11_12','The source is an official model selector, not a version-specific brochure PDF.','Ducati factory manuals, maintenance schedules and brochures library'),
(107,'factory_documents','Ducati Panigale V4 — official model brochure library','{"document_url":"https://www.ducati.com/gb/en/bikes/brochures","applicability":"Confirm model year and standard V4 versus V4 S or V4 R; brochures may reflect current factory range","document_type":"Manufacturer brochure selection","document_title":"Ducati model brochures — select Panigale V4"}'::jsonb,NULL,NULL,'United Kingdom','Ducati official model brochure library','https://www.ducati.com/gb/en/bikes/brochures','official_factory_document_archive_verified_2026_11_12','Official brochure selector; no claim about specific older Panigale V4 editions being available in archive.','Ducati official model brochure library'),
(102,'used_buying','Ducati Monster 937 — ownership documentation checks','{"checks":["Match the motorcycle''s model year and variant to the manufacturer''s owner manual","Check servicing evidence against the official maintenance schedule for its exact year","Check any open safety or updating campaigns through Ducati''s official resources"],"source_scope":"Official Ducati documentation and maintenance information; checks are guidance, not evidence of a defect on any individual motorcycle"}'::jsonb,2021,NULL,'United Kingdom','Ducati factory manuals, parts and maintenance schedules','https://www.ducati.com/ww/en/service-maintenance/manuals-genuine-parts-and-maintenance-schedules','official_factory_document_archive_verified_2026_11_12','Evidence-driven ownership guidance, not an unsupported mechanical fault list; not a substitute for professional inspection.','Ducati factory manuals, parts and maintenance schedules')
)
insert into public.motorcycle_catalog_facts(catalog_model_id,category,label,value,start_year,end_year,market,source_name,source_url,verification_status)
select d.catalog_model_id,d.category,d.label,d.value,d.start_year,d.end_year,d.market,d.source_name,d.source_url,'verified'
from documented d where exists(select 1 from public.motorcycle_catalog_dropdown_clean m where m.model_id=d.catalog_model_id)
and not exists(select 1 from public.motorcycle_catalog_facts f where f.catalog_model_id=d.catalog_model_id and f.label=d.label and f.source_url=d.source_url);

with documented(catalog_model_id,label,source_url,verification_basis,scope_note,source_version) as (values
(102,'Ducati Monster 937 — official owner manual archive','https://www.ducati.com/gb/en/service-maintenance/owner-manuals','official_factory_document_archive_verified_2026_11_12','This is the official selector, NOT a claim that a specific owner manual PDF has been downloaded or inspected.','Ducati official owner-manual archive'),
(104,'Ducati Multistrada V4 — official factory manuals and brochures','https://www.ducati.com/ww/en/service-maintenance/manuals-genuine-parts-and-maintenance-schedules','official_factory_document_archive_verified_2026_11_12','The source is an official model selector, not a version-specific brochure PDF.','Ducati factory manuals, maintenance schedules and brochures library'),
(107,'Ducati Panigale V4 — official model brochure library','https://www.ducati.com/gb/en/bikes/brochures','official_factory_document_archive_verified_2026_11_12','Official brochure selector; no claim about specific older Panigale V4 editions being available in archive.','Ducati official model brochure library'),
(102,'Ducati Monster 937 — ownership documentation checks','https://www.ducati.com/ww/en/service-maintenance/manuals-genuine-parts-and-maintenance-schedules','official_factory_document_archive_verified_2026_11_12','Evidence-driven ownership guidance, not an unsupported mechanical fault list; not a substitute for professional inspection.','Ducati factory manuals, parts and maintenance schedules')
)
insert into public.motorcycle_catalog_fact_verification_audit(fact_id,checked_at,verification_basis,source_url,scope_note,source_version)
select f.id,now(),d.verification_basis,d.source_url,d.scope_note,d.source_version from documented d
join public.motorcycle_catalog_facts f on f.catalog_model_id=d.catalog_model_id and f.label=d.label and f.source_url=d.source_url
where not exists(select 1 from public.motorcycle_catalog_fact_verification_audit a where a.fact_id=f.id);
